using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Accounts.Admin;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin.Profiles;[Authorize(Policy="AccountAdmin")]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public IReadOnlyList<Row>Profiles{get;private set;}=[];public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();var counts=await db.AccountMembers.AsNoTracking().Where(x=>x.AccountId==account&&!x.IsDeleted).GroupBy(x=>x.RoleCode).ToDictionaryAsync(x=>x.Key,x=>x.Count(),ct);Profiles=ProfilePermissionMatrix.AccountProfiles.OrderBy(x=>x).Select(x=>new Row(x,counts.GetValueOrDefault(x))).ToArray();return Page();}public sealed record Row(string Name,int Members);}
